def _bind() -> ctypes.CDLL:
    lib = _load()
    for _, (export, argtypes, restype) in _BINDINGS.items():
        fn = getattr(lib, export)
        fn.argtypes = argtypes
        fn.restype = restype
    return lib


def _call(c_name: str, *args):
    export = _BINDINGS[c_name][0]
    return getattr(_bind(), export)(*args)


